CREATE TABLE IF NOT EXISTS schema_version(version VARCHAR(40) PRIMARY KEY,applied_at TIMESTAMPTZ DEFAULT NOW());
INSERT INTO schema_version(version) VALUES('4.2.2.1-r2') ON CONFLICT DO NOTHING;
CREATE TABLE IF NOT EXISTS roles(codigo VARCHAR(30) PRIMARY KEY,nombre VARCHAR(100) NOT NULL,alcance VARCHAR(20) NOT NULL CHECK(alcance IN ('GLOBAL','INMUEBLE','ESPACIO')),es_sistema BOOLEAN DEFAULT TRUE,activo BOOLEAN DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS permisos(codigo VARCHAR(80) PRIMARY KEY,nombre VARCHAR(160) NOT NULL,modulo VARCHAR(60),accion VARCHAR(30),activo BOOLEAN DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS rol_permisos(rol_codigo VARCHAR(30) REFERENCES roles(codigo),permiso_codigo VARCHAR(80) REFERENCES permisos(codigo),permitido BOOLEAN DEFAULT TRUE,PRIMARY KEY(rol_codigo,permiso_codigo));
CREATE TABLE IF NOT EXISTS catalogos(id BIGSERIAL PRIMARY KEY,codigo VARCHAR(60) UNIQUE,nombre VARCHAR(120),activo BOOLEAN DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS catalogo_valores(id BIGSERIAL PRIMARY KEY,catalogo_id BIGINT REFERENCES catalogos(id),codigo VARCHAR(80),nombre VARCHAR(160),activo BOOLEAN DEFAULT TRUE,UNIQUE(catalogo_id,codigo));
CREATE TABLE IF NOT EXISTS condominios(id BIGSERIAL PRIMARY KEY,clave VARCHAR(40) UNIQUE NOT NULL,nombre VARCHAR(200) NOT NULL,tipo_codigo VARCHAR(80),direccion TEXT,rfc VARCHAR(20),moneda_base VARCHAR(3) DEFAULT 'MXN',zona_horaria VARCHAR(80) DEFAULT 'America/Mexico_City',logo_data BYTEA,logo_mime VARCHAR(60),portada_data BYTEA,portada_mime VARCHAR(60),activo BOOLEAN DEFAULT TRUE,creado_en TIMESTAMPTZ DEFAULT NOW(),actualizado_en TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS usuarios(id BIGSERIAL PRIMARY KEY,username VARCHAR(100) UNIQUE NOT NULL,nombre VARCHAR(200) NOT NULL,email VARCHAR(254),telefono VARCHAR(50),rol_global VARCHAR(30) NOT NULL DEFAULT 'USUARIO' CHECK(rol_global IN ('SUPERADMIN','USUARIO')),salt TEXT NOT NULL,password_hash TEXT NOT NULL,email_verificado BOOLEAN DEFAULT FALSE,debe_cambiar_password BOOLEAN DEFAULT FALSE,intentos_fallidos INT DEFAULT 0,bloqueado_hasta TIMESTAMPTZ,ultimo_acceso TIMESTAMPTZ,activo BOOLEAN DEFAULT TRUE,creado_en TIMESTAMPTZ DEFAULT NOW(),actualizado_en TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS usuario_inmuebles(usuario_id BIGINT REFERENCES usuarios(id) ON DELETE CASCADE,condominio_id BIGINT REFERENCES condominios(id) ON DELETE CASCADE,rol_codigo VARCHAR(30) REFERENCES roles(codigo),activo BOOLEAN DEFAULT TRUE,asignado_por BIGINT REFERENCES usuarios(id),asignado_en TIMESTAMPTZ DEFAULT NOW(),revocado_por BIGINT REFERENCES usuarios(id),revocado_en TIMESTAMPTZ,PRIMARY KEY(usuario_id,condominio_id,rol_codigo));
CREATE TABLE IF NOT EXISTS espacios(id BIGSERIAL PRIMARY KEY,condominio_id BIGINT REFERENCES condominios(id),nombre VARCHAR(80),tipo_codigo VARCHAR(80),estado_codigo VARCHAR(80),cuota_base NUMERIC(14,2) DEFAULT 0,indiviso_pct NUMERIC(7,4) DEFAULT 0,activo BOOLEAN DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS personas(id BIGSERIAL PRIMARY KEY,nombre VARCHAR(200),email VARCHAR(254),telefono VARCHAR(50),activo BOOLEAN DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS persona_espacios(id BIGSERIAL PRIMARY KEY,persona_id BIGINT REFERENCES personas(id),espacio_id BIGINT REFERENCES espacios(id),tipo_relacion VARCHAR(80),fecha_inicio DATE,fecha_fin DATE,activo BOOLEAN DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS usuario_espacios(usuario_id BIGINT REFERENCES usuarios(id),espacio_id BIGINT REFERENCES espacios(id),tipo_relacion VARCHAR(80),activo BOOLEAN DEFAULT TRUE,PRIMARY KEY(usuario_id,espacio_id));
CREATE TABLE IF NOT EXISTS cargos(id BIGSERIAL PRIMARY KEY,condominio_id BIGINT REFERENCES condominios(id),espacio_id BIGINT REFERENCES espacios(id),periodo VARCHAR(7),tipo_codigo VARCHAR(80),concepto VARCHAR(200),monto_mxn NUMERIC(14,2) DEFAULT 0,activo BOOLEAN DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS pagos(id BIGSERIAL PRIMARY KEY,condominio_id BIGINT REFERENCES condominios(id),espacio_id BIGINT REFERENCES espacios(id),periodo VARCHAR(7),fecha DATE,monto_mxn NUMERIC(14,2) DEFAULT 0,activo BOOLEAN DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS gastos(id BIGSERIAL PRIMARY KEY,condominio_id BIGINT REFERENCES condominios(id),fecha DATE,categoria_codigo VARCHAR(80),concepto VARCHAR(200),monto_mxn NUMERIC(14,2) DEFAULT 0,activo BOOLEAN DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS presupuestos(id BIGSERIAL PRIMARY KEY,condominio_id BIGINT REFERENCES condominios(id),anio INT,mes INT,categoria_codigo VARCHAR(80),monto_mxn NUMERIC(14,2) DEFAULT 0,activo BOOLEAN DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS auditoria(id BIGSERIAL PRIMARY KEY,condominio_id BIGINT,fecha TIMESTAMPTZ DEFAULT NOW(),usuario_id BIGINT,username VARCHAR(100),accion VARCHAR(100),entidad VARCHAR(80),entidad_id BIGINT,detalle TEXT,valor_anterior JSONB,valor_nuevo JSONB,resultado VARCHAR(20) DEFAULT 'OK');
CREATE INDEX IF NOT EXISTS idx_usuario_inmuebles_scope ON usuario_inmuebles(usuario_id,condominio_id,activo);
CREATE INDEX IF NOT EXISTS idx_espacios_condominio ON espacios(condominio_id,activo);
CREATE INDEX IF NOT EXISTS idx_cargos_condominio_periodo ON cargos(condominio_id,periodo);
CREATE INDEX IF NOT EXISTS idx_auditoria_condominio_fecha ON auditoria(condominio_id,fecha DESC);
